  package main
  import ("encoding/json"; "net/http")

  func tareas(w http.ResponseWriter, r *http.Request) {
      w.Header().Set("Content-Type", "application/json")
      switch r.Method {
      case "GET":
          lista := []map[string]any{{"id": 1, "titulo": "Aprender Go"}}
          json.NewEncoder(w).Encode(lista)
      case "POST":
